values ('e-7dias-oracao-palavra', $json${"id":"e-7dias-oracao-palavra","title":"7 dias de oração e Palavra","author":"Íntima Graça","category":"Jornadas de 21/30 dias","price":0,"coverColor":"#344E41","coverImage":null,"year":2026,"holder":"Íntima Graça","isbn":"","creditsText":"Versículos na tradução Almeida Corrigida Fiel (domínio público).","creditsPosition":"back","coverStyles":{"cover-title":{"font":"Cormorant Garamond","size":9,"bold":true,"align":"center","color":"#F8F6F0"},"cover-author":{"font":"Manrope","size":3.6,"align":"center","color":"#C6A667"}},"published":true,"pages":[{"id":"p-dia-1","bg":"#F8F6F0","blocks":[{"id":"k-1-1","font":"Cormorant Garamond","size":8.5,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"7 dias de oração e Palavra"},{"id":"k-1-2","style":"ornament","color":"#C6A667","thickness":2,"width":40,"align":"center","type":"line"},{"id":"k-1-3","font":"Manrope","size":4.2,"color":"#344E41","bold":false,"italic":false,"underline":false,"align":"center","type":"text","text":"Uma semana para criar o hábito de orar e ler a Bíblia, com um pequeno desafio por dia."},{"id":"k-1-4","font":"Cormorant Garamond","size":6.5,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Como usar"},{"id":"k-1-5","font":"Manrope","size":4,"color":"#344E41","bold":false,"italic":false,"underline":false,"align":"justify","type":"text","text":"Cada dia tem duas páginas: o desafio de leitura da Bíblia e o desafio de oração. Reserve de 10 a 15 minutos, sempre no mesmo horário, e tenha por perto uma Bíblia e um caderno."}]},{"id":"p-dia-2","bg":"#F8F6F0","blocks":[{"id":"k-2-1","font":"Cormorant Garamond","size":5.5,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Dia 1"},{"id":"k-2-2","font":"Cormorant Garamond","size":7.5,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Aquietar o coração"},{"id":"k-2-3","style":"ornament","color":"#C6A667","thickness":2,"width":40,"align":"center","type":"line"},{"id":"k-2-4","font":"Cormorant Garamond","size":6.2,"color":"#344E41","bold":false,"italic":true,"underline":false,"align":"center","type":"text","text":"“Aquietai-vos, e sabei que eu sou Deus; serei exaltado entre as nações, serei exaltado sobre a terra.”"},{"id":"k-2-5","font":"Manrope","size":3.2,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Salmos 46:10"}]},{"id":"p-dia-3","bg":"#FFFFFF","blocks":[{"id":"k-3-1","font":"Cormorant Garamond","size":5.5,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Dia 1"},{"id":"k-3-2","font":"Cormorant Garamond","size":7,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Desafio de leitura"},{"id":"k-3-3","style":"ornament","color":"#C6A667","thickness":2,"width":40,"align":"center","type":"line"},{"id":"k-3-4","font":"Cormorant Garamond","size":6,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Salmos 46"},{"id":"k-3-5","font":"Manrope","size":3.8,"color":"#344E41","bold":false,"italic":false,"underline":false,"align":"left","type":"text","text":"Leia o Salmo 46 inteiro, devagar, em voz baixa. Depois escreva em uma frase o que chamou sua atenção."},{"id":"k-3-6","font":"Manrope","size":3.2,"color":"#5b6b62","bold":false,"italic":false,"underline":false,"align":"left","type":"text","text":"Anote o que a leitura falou ao seu coração:"},{"id":"k-3-7","style":"dotted","color":"#A3B18A","thickness":2,"width":100,"align":"center","type":"line"},{"id":"k-3-8","style":"dotted","color":"#A3B18A","thickness":2,"width":100,"align":"center","type":"line"}]},{"id":"p-dia-4","bg":"#F8F6F0","blocks":[{"id":"k-4-1","font":"Cormorant Garamond","size":5.5,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Dia 1"},{"id":"k-4-2","font":"Cormorant Garamond","size":7,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Desafio de oração"},{"id":"k-4-3","style":"ornament","color":"#C6A667","thickness":2,"width":40,"align":"center","type":"line"},{"id":"k-4-4","font":"Manrope","size":3.8,"color":"#344E41","bold":false,"italic":false,"underline":false,"align":"left","type":"text","text":"Fique 5 minutos em silêncio diante de Deus, sem pedir nada. Apenas respire e diga: “Senhor, estou aqui.”"},{"id":"k-4-5","style":"fade","color":"#C6A667","thickness":2,"width":70,"align":"center","type":"line"},{"id":"k-4-6","font":"Cormorant Garamond","size":6,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Oração do dia"},{"id":"k-4-7","font":"Manrope","size":3.8,"color":"#344E41","bold":false,"italic":true,"underline":false,"align":"left","type":"text","text":"Pai, aquieta o meu coração e a minha mente. Ensina-me a confiar que tu és Deus sobre todas as coisas. Amém."}]},{"id":"p-dia-5","bg":"#F8F6F0","blocks":[{"id":"k-5-1","font":"Cormorant Garamond","size":5.5,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Dia 2"},{"id":"k-5-2","font":"Cormorant Garamond","size":7.5,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Orar em secreto"},{"id":"k-5-3","style":"ornament","color":"#C6A667","thickness":2,"width":40,"align":"center","type":"line"},{"id":"k-5-4","font":"Cormorant Garamond","size":6.2,"color":"#344E41","bold":false,"italic":true,"underline":false,"align":"center","type":"text","text":"“Mas tu, quando orares, entra no teu aposento e, fechada a porta, ora a teu Pai que está em secreto; e teu Pai, que vê em secreto, te recompensará publicamente.”"},{"id":"k-5-5","font":"Manrope","size":3.2,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Mateus 6:6"}]},{"id":"p-dia-6","bg":"#FFFFFF","blocks":[{"id":"k-6-1","font":"Cormorant Garamond","size":5.5,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Dia 2"},{"id":"k-6-2","font":"Cormorant Garamond","size":7,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Desafio de leitura"},{"id":"k-6-3","style":"ornament","color":"#C6A667","thickness":2,"width":40,"align":"center","type":"line"},{"id":"k-6-4","font":"Cormorant Garamond","size":6,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Mateus 6:5-15"},{"id":"k-6-5","font":"Manrope","size":3.8,"color":"#344E41","bold":false,"italic":false,"underline":false,"align":"left","type":"text","text":"Leia Mateus 6:5-15 e sublinhe as palavras que se repetem. O que Jesus mais quer que você perceba sobre a oração?"},{"id":"k-6-6","font":"Manrope","size":3.2,"color":"#5b6b62","bold":false,"italic":false,"underline":false,"align":"left","type":"text","text":"Anote o que a leitura falou ao seu coração:"},{"id":"k-6-7","style":"dotted","color":"#A3B18A","thickness":2,"width":100,"align":"center","type":"line"},{"id":"k-6-8","style":"dotted","color":"#A3B18A","thickness":2,"width":100,"align":"center","type":"line"}]},{"id":"p-dia-7","bg":"#F8F6F0","blocks":[{"id":"k-7-1","font":"Cormorant Garamond","size":5.5,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Dia 2"},{"id":"k-7-2","font":"Cormorant Garamond","size":7,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Desafio de oração"},{"id":"k-7-3","style":"ornament","color":"#C6A667","thickness":2,"width":40,"align":"center","type":"line"},{"id":"k-7-4","font":"Manrope","size":3.8,"color":"#344E41","bold":false,"italic":false,"underline":false,"align":"left","type":"text","text":"Escolha um lugar da casa para ser o seu cantinho de oração. Passe 10 minutos ali, sem celular por perto."},{"id":"k-7-5","style":"fade","color":"#C6A667","thickness":2,"width":70,"align":"center","type":"line"},{"id":"k-7-6","font":"Cormorant Garamond","size":6,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Oração do dia"},{"id":"k-7-7","font":"Manrope","size":3.8,"color":"#344E41","bold":false,"italic":true,"underline":false,"align":"left","type":"text","text":"Senhor, ensina-me a orar. Que o meu coração te procure com sinceridade, longe do barulho e das aparências. Amém."}]},{"id":"p-dia-8","bg":"#F8F6F0","blocks":[{"id":"k-8-1","font":"Cormorant Garamond","size":5.5,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Dia 3"},{"id":"k-8-2","font":"Cormorant Garamond","size":7.5,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Entregar a ansiedade"},{"id":"k-8-3","style":"ornament","color":"#C6A667","thickness":2,"width":40,"align":"center","type":"line"},{"id":"k-8-4","font":"Cormorant Garamond","size":6.2,"color":"#344E41","bold":false,"italic":true,"underline":false,"align":"center","type":"text","text":"“Não estejais inquietos por coisa alguma; antes as vossas petições sejam em tudo conhecidas diante de Deus pela oração e súplica, com ação de graças.”"},{"id":"k-8-5","font":"Manrope","size":3.2,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Filipenses 4:6"}]},{"id":"p-dia-9","bg":"#FFFFFF","blocks":[{"id":"k-9-1","font":"Cormorant Garamond","size":5.5,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Dia 3"},{"id":"k-9-2","font":"Cormorant Garamond","size":7,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Desafio de leitura"},{"id":"k-9-3","style":"ornament","color":"#C6A667","thickness":2,"width":40,"align":"center","type":"line"},{"id":"k-9-4","font":"Cormorant Garamond","size":6,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Filipenses 4:4-9"},{"id":"k-9-5","font":"Manrope","size":3.8,"color":"#344E41","bold":false,"italic":false,"underline":false,"align":"left","type":"text","text":"Leia Filipenses 4:4-9. Faça duas colunas num papel: “o que me preocupa” e “o que Deus prometeu”."},{"id":"k-9-6","font":"Manrope","size":3.2,"color":"#5b6b62","bold":false,"italic":false,"underline":false,"align":"left","type":"text","text":"Anote o que a leitura falou ao seu coração:"},{"id":"k-9-7","style":"dotted","color":"#A3B18A","thickness":2,"width":100,"align":"center","type":"line"},{"id":"k-9-8","style":"dotted","color":"#A3B18A","thickness":2,"width":100,"align":"center","type":"line"}]},{"id":"p-dia-10","bg":"#F8F6F0","blocks":[{"id":"k-10-1","font":"Cormorant Garamond","size":5.5,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Dia 3"},{"id":"k-10-2","font":"Cormorant Garamond","size":7,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Desafio de oração"},{"id":"k-10-3","style":"ornament","color":"#C6A667","thickness":2,"width":40,"align":"center","type":"line"},{"id":"k-10-4","font":"Manrope","size":3.8,"color":"#344E41","bold":false,"italic":false,"underline":false,"align":"left","type":"text","text":"Ore citando cada preocupação da sua lista, uma a uma, e termine agradecendo por três coisas que já recebeu."},{"id":"k-10-5","style":"fade","color":"#C6A667","thickness":2,"width":70,"align":"center","type":"line"},{"id":"k-10-6","font":"Cormorant Garamond","size":6,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Oração do dia"},{"id":"k-10-7","font":"Manrope","size":3.8,"color":"#344E41","bold":false,"italic":true,"underline":false,"align":"left","type":"text","text":"Deus de paz, eu entrego a ti cada preocupação. Guarda o meu coração e os meus pensamentos em Cristo Jesus. Amém."}]},{"id":"p-dia-11","bg":"#F8F6F0","blocks":[{"id":"k-11-1","font":"Cormorant Garamond","size":5.5,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Dia 4"},{"id":"k-11-2","font":"Cormorant Garamond","size":7.5,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Luz para o caminho"},{"id":"k-11-3","style":"ornament","color":"#C6A667","thickness":2,"width":40,"align":"center","type":"line"},{"id":"k-11-4","font":"Cormorant Garamond","size":6.2,"color":"#344E41","bold":false,"italic":true,"underline":false,"align":"center","type":"text","text":"“Lâmpada para os meus pés é tua palavra, e luz para o meu caminho.”"},{"id":"k-11-5","font":"Manrope","size":3.2,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Salmos 119:105"}]},{"id":"p-dia-12","bg":"#FFFFFF","blocks":[{"id":"k-12-1","font":"Cormorant Garamond","size":5.5,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Dia 4"},{"id":"k-12-2","font":"Cormorant Garamond","size":7,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Desafio de leitura"},{"id":"k-12-3","style":"ornament","color":"#C6A667","thickness":2,"width":40,"align":"center","type":"line"},{"id":"k-12-4","font":"Cormorant Garamond","size":6,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Salmos 119:97-112"},{"id":"k-12-5","font":"Manrope","size":3.8,"color":"#344E41","bold":false,"italic":false,"underline":false,"align":"left","type":"text","text":"Leia Salmos 119:97-112 e escolha um versículo para decorar hoje. Repita-o três vezes ao longo do dia."},{"id":"k-12-6","font":"Manrope","size":3.2,"color":"#5b6b62","bold":false,"italic":false,"underline":false,"align":"left","type":"text","text":"Anote o que a leitura falou ao seu coração:"},{"id":"k-12-7","style":"dotted","color":"#A3B18A","thickness":2,"width":100,"align":"center","type":"line"},{"id":"k-12-8","style":"dotted","color":"#A3B18A","thickness":2,"width":100,"align":"center","type":"line"}]},{"id":"p-dia-13","bg":"#F8F6F0","blocks":[{"id":"k-13-1","font":"Cormorant Garamond","size":5.5,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Dia 4"},{"id":"k-13-2","font":"Cormorant Garamond","size":7,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Desafio de oração"},{"id":"k-13-3","style":"ornament","color":"#C6A667","thickness":2,"width":40,"align":"center","type":"line"},{"id":"k-13-4","font":"Manrope","size":3.8,"color":"#344E41","bold":false,"italic":false,"underline":false,"align":"left","type":"text","text":"Peça a Deus direção para uma decisão que está pendente e anote o que vier ao seu coração depois da oração."},{"id":"k-13-5","style":"fade","color":"#C6A667","thickness":2,"width":70,"align":"center","type":"line"},{"id":"k-13-6","font":"Cormorant Garamond","size":6,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Oração do dia"},{"id":"k-13-7","font":"Manrope","size":3.8,"color":"#344E41","bold":false,"italic":true,"underline":false,"align":"left","type":"text","text":"Senhor, que a tua palavra seja a luz dos meus passos. Mostra-me o caminho e dá-me coragem para andar nele. Amém."}]},{"id":"p-dia-14","bg":"#F8F6F0","blocks":[{"id":"k-14-1","font":"Cormorant Garamond","size":5.5,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Dia 5"},{"id":"k-14-2","font":"Cormorant Garamond","size":7.5,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Gratidão em tudo"},{"id":"k-14-3","style":"ornament","color":"#C6A667","thickness":2,"width":40,"align":"center","type":"line"},{"id":"k-14-4","font":"Cormorant Garamond","size":6.2,"color":"#344E41","bold":false,"italic":true,"underline":false,"align":"center","type":"text","text":"“Estai sempre alegres; orai sem cessar; em tudo dai graças, porque esta é a vontade de Deus em Cristo Jesus para convosco.”"},{"id":"k-14-5","font":"Manrope","size":3.2,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"1 Tessalonicenses 5:16-18"}]},{"id":"p-dia-15","bg":"#FFFFFF","blocks":[{"id":"k-15-1","font":"Cormorant Garamond","size":5.5,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Dia 5"},{"id":"k-15-2","font":"Cormorant Garamond","size":7,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Desafio de leitura"},{"id":"k-15-3","style":"ornament","color":"#C6A667","thickness":2,"width":40,"align":"center","type":"line"},{"id":"k-15-4","font":"Cormorant Garamond","size":6,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"1 Tessalonicenses 5:12-28"},{"id":"k-15-5","font":"Manrope","size":3.8,"color":"#344E41","bold":false,"italic":false,"underline":false,"align":"left","type":"text","text":"Leia 1 Tessalonicenses 5:12-28 e destaque os verbos de ação. Escolha um para praticar hoje."},{"id":"k-15-6","font":"Manrope","size":3.2,"color":"#5b6b62","bold":false,"italic":false,"underline":false,"align":"left","type":"text","text":"Anote o que a leitura falou ao seu coração:"},{"id":"k-15-7","style":"dotted","color":"#A3B18A","thickness":2,"width":100,"align":"center","type":"line"},{"id":"k-15-8","style":"dotted","color":"#A3B18A","thickness":2,"width":100,"align":"center","type":"line"}]},{"id":"p-dia-16","bg":"#F8F6F0","blocks":[{"id":"k-16-1","font":"Cormorant Garamond","size":5.5,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Dia 5"},{"id":"k-16-2","font":"Cormorant Garamond","size":7,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Desafio de oração"},{"id":"k-16-3","style":"ornament","color":"#C6A667","thickness":2,"width":40,"align":"center","type":"line"},{"id":"k-16-4","font":"Manrope","size":3.8,"color":"#344E41","bold":false,"italic":false,"underline":false,"align":"left","type":"text","text":"Faça uma oração só de gratidão: agradeça por dez coisas, das maiores às mais simples, sem pedir nada."},{"id":"k-16-5","style":"fade","color":"#C6A667","thickness":2,"width":70,"align":"center","type":"line"},{"id":"k-16-6","font":"Cormorant Garamond","size":6,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Oração do dia"},{"id":"k-16-7","font":"Manrope","size":3.8,"color":"#344E41","bold":false,"italic":true,"underline":false,"align":"left","type":"text","text":"Pai, obrigada(o) por tudo o que és e por tudo o que fazes. Que a gratidão seja o meu jeito de viver. Amém."}]},{"id":"p-dia-17","bg":"#F8F6F0","blocks":[{"id":"k-17-1","font":"Cormorant Garamond","size":5.5,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Dia 6"},{"id":"k-17-2","font":"Cormorant Garamond","size":7.5,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Orar uns pelos outros"},{"id":"k-17-3","style":"ornament","color":"#C6A667","thickness":2,"width":40,"align":"center","type":"line"},{"id":"k-17-4","font":"Cormorant Garamond","size":6.2,"color":"#344E41","bold":false,"italic":true,"underline":false,"align":"center","type":"text","text":"“Confessai as vossas culpas uns aos outros, e orai uns pelos outros, para que sareis; a oração feita por um justo pode muito em seus efeitos.”"},{"id":"k-17-5","font":"Manrope","size":3.2,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Tiago 5:16"}]},{"id":"p-dia-18","bg":"#FFFFFF","blocks":[{"id":"k-18-1","font":"Cormorant Garamond","size":5.5,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Dia 6"},{"id":"k-18-2","font":"Cormorant Garamond","size":7,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Desafio de leitura"},{"id":"k-18-3","style":"ornament","color":"#C6A667","thickness":2,"width":40,"align":"center","type":"line"},{"id":"k-18-4","font":"Cormorant Garamond","size":6,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Tiago 5:13-20"},{"id":"k-18-5","font":"Manrope","size":3.8,"color":"#344E41","bold":false,"italic":false,"underline":false,"align":"left","type":"text","text":"Leia Tiago 5:13-20 e pense: quem na sua vida precisa de oração hoje? Escreva três nomes."},{"id":"k-18-6","font":"Manrope","size":3.2,"color":"#5b6b62","bold":false,"italic":false,"underline":false,"align":"left","type":"text","text":"Anote o que a leitura falou ao seu coração:"},{"id":"k-18-7","style":"dotted","color":"#A3B18A","thickness":2,"width":100,"align":"center","type":"line"},{"id":"k-18-8","style":"dotted","color":"#A3B18A","thickness":2,"width":100,"align":"center","type":"line"}]},{"id":"p-dia-19","bg":"#F8F6F0","blocks":[{"id":"k-19-1","font":"Cormorant Garamond","size":5.5,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Dia 6"},{"id":"k-19-2","font":"Cormorant Garamond","size":7,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Desafio de oração"},{"id":"k-19-3","style":"ornament","color":"#C6A667","thickness":2,"width":40,"align":"center","type":"line"},{"id":"k-19-4","font":"Manrope","size":3.8,"color":"#344E41","bold":false,"italic":false,"underline":false,"align":"left","type":"text","text":"Ore por cada um dos três nomes e envie uma mensagem curta de carinho a pelo menos uma dessas pessoas."},{"id":"k-19-5","style":"fade","color":"#C6A667","thickness":2,"width":70,"align":"center","type":"line"},{"id":"k-19-6","font":"Cormorant Garamond","size":6,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Oração do dia"},{"id":"k-19-7","font":"Manrope","size":3.8,"color":"#344E41","bold":false,"italic":true,"underline":false,"align":"left","type":"text","text":"Senhor, cuida das pessoas que amo. Dá-lhes saúde, paz e esperança, e usa-me para abençoar a vida delas. Amém."}]},{"id":"p-dia-20","bg":"#F8F6F0","blocks":[{"id":"k-20-1","font":"Cormorant Garamond","size":5.5,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Dia 7"},{"id":"k-20-2","font":"Cormorant Garamond","size":7.5,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Confiar e seguir"},{"id":"k-20-3","style":"ornament","color":"#C6A667","thickness":2,"width":40,"align":"center","type":"line"},{"id":"k-20-4","font":"Cormorant Garamond","size":6.2,"color":"#344E41","bold":false,"italic":true,"underline":false,"align":"center","type":"text","text":"“Não to mandei eu? Esforça-te, e tem bom ânimo; não temas, nem te espantes, porque o Senhor teu Deus é contigo, por onde quer que andares.”"},{"id":"k-20-5","font":"Manrope","size":3.2,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Josué 1:9"}]},{"id":"p-dia-21","bg":"#FFFFFF","blocks":[{"id":"k-21-1","font":"Cormorant Garamond","size":5.5,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Dia 7"},{"id":"k-21-2","font":"Cormorant Garamond","size":7,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Desafio de leitura"},{"id":"k-21-3","style":"ornament","color":"#C6A667","thickness":2,"width":40,"align":"center","type":"line"},{"id":"k-21-4","font":"Cormorant Garamond","size":6,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Josué 1:1-9"},{"id":"k-21-5","font":"Manrope","size":3.8,"color":"#344E41","bold":false,"italic":false,"underline":false,"align":"left","type":"text","text":"Leia Josué 1:1-9 e escreva com suas palavras a promessa que Deus faz a Josué. Ela vale também para você."},{"id":"k-21-6","font":"Manrope","size":3.2,"color":"#5b6b62","bold":false,"italic":false,"underline":false,"align":"left","type":"text","text":"Anote o que a leitura falou ao seu coração:"},{"id":"k-21-7","style":"dotted","color":"#A3B18A","thickness":2,"width":100,"align":"center","type":"line"},{"id":"k-21-8","style":"dotted","color":"#A3B18A","thickness":2,"width":100,"align":"center","type":"line"}]},{"id":"p-dia-22","bg":"#F8F6F0","blocks":[{"id":"k-22-1","font":"Cormorant Garamond","size":5.5,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Dia 7"},{"id":"k-22-2","font":"Cormorant Garamond","size":7,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Desafio de oração"},{"id":"k-22-3","style":"ornament","color":"#C6A667","thickness":2,"width":40,"align":"center","type":"line"},{"id":"k-22-4","font":"Manrope","size":3.8,"color":"#344E41","bold":false,"italic":false,"underline":false,"align":"left","type":"text","text":"Ore declarando o seu próximo passo com Deus. Defina um hábito simples de oração e leitura para os próximos 30 dias."},{"id":"k-22-5","style":"fade","color":"#C6A667","thickness":2,"width":70,"align":"center","type":"line"},{"id":"k-22-6","font":"Cormorant Garamond","size":6,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Oração do dia"},{"id":"k-22-7","font":"Manrope","size":3.8,"color":"#344E41","bold":false,"italic":true,"underline":false,"align":"left","type":"text","text":"Deus fiel, tu és comigo por onde eu for. Dá-me bom ânimo para continuar buscando-te todos os dias. Amém."}]},{"id":"p-dia-23","bg":"#F8F6F0","blocks":[{"id":"k-23-1","font":"Cormorant Garamond","size":8,"color":"#344E41","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Você chegou ao sétimo dia"},{"id":"k-23-2","style":"ornament","color":"#C6A667","thickness":2,"width":40,"align":"center","type":"line"},{"id":"k-23-3","font":"Manrope","size":4,"color":"#344E41","bold":false,"italic":false,"underline":false,"align":"justify","type":"text","text":"Olhe para trás: sete dias de encontro com Deus. Não pare por aqui. Escolha um horário fixo, uma passagem para ler e uma pessoa por quem orar, e continue."},{"id":"k-23-4","font":"Cormorant Garamond","size":6.2,"color":"#344E41","bold":false,"italic":true,"underline":false,"align":"center","type":"text","text":"“Esforça-te, e tem bom ânimo.”"},{"id":"k-23-5","font":"Manrope","size":3.2,"color":"#8A6D2F","bold":true,"italic":false,"underline":false,"align":"center","type":"text","text":"Josué 1:9"}]}]}$json$::jsonb, now())
on conflict (book_id) do update set data = excluded.data, updated_at = now();

-- Conferência
select b.id, b.title, b.category, b.price, b.published,
       jsonb_array_length(c.data -> 'pages') as paginas
from public.books b join public.book_content c on c.book_id = b.id
where b.id = 'e-7dias-oracao-palavra';
